from types import SimpleNamespace

# This sandbox has no network and no API key, so FakeAnthropic stands in for
# anthropic.Anthropic(). client.messages.create(...) takes the same arguments as the
# real SDK and returns an object shaped like the real Message response.
class _Messages:
    def __init__(self):
        self.last_request = None

    def create(self, model, max_tokens, messages, system=None, **kwargs):
        self.last_request = {"model": model, "max_tokens": max_tokens,
                             "messages": messages, "system": system}
        for m in messages:
            if m["role"] not in ("user", "assistant"):
                raise ValueError("messages may only use the roles 'user' and 'assistant' - "
                                 "pass the system prompt with system=...")
        if not messages or messages[0]["role"] != "user":
            raise ValueError("the first message must have role 'user'")
        text = "Review: rename calc, x, y and r to descriptive names and add a docstring."
        prompt_words = len((system or "").split()) + sum(len(m["content"].split()) for m in messages)
        return SimpleNamespace(
            content=[SimpleNamespace(type="text", text=text)],
            usage=SimpleNamespace(input_tokens=prompt_words, output_tokens=len(text.split())),
            stop_reason="end_turn",
        )


class FakeAnthropic:
    def __init__(self, api_key=None):
        if not api_key:
            raise ValueError("api_key is required")   # the real SDK raises an AuthenticationError
        self.messages = _Messages()


